/**
 * Agent-memory ADMISSION GATE — the graphify-side of the ratified contract
 * SPEC_AGENT_MEMORY_SUBSTRATE (@87a8cd05..d8a4a448, wire-shape §9.4).
 *
 * graphify DEFINES this gate; h2a imports only the SIGNATURE and never graphify
 * internals; this module imports NOTHING from h2a (anti-cycle). graphify authors
 * NO memory content — it VALIDATES a caller-built note and stamps the fixed
 * admission fields only.
 *
 * Perimeter (this module): the admission checks (§3.1 schema/enum; §3.3 persona
 * = subject + STRUCTURAL event_shaped + single-note/no-profile; §3.4
 * reconcilable:false; §3.5 subject-human retention + tombstone authority; §3.6
 * principal_owner/scope neutral hook; §4 verifyVerbatim citation). OUT of scope:
 * the storage write-path (injected as a dependency), the D11 promotion rule, and
 * the parked executive/projection logic (§3.6).
 *
 * Deterministic, provider-neutral, no LLM, no network.
 */
import { createHash } from "node:crypto";
import { normalizeForMatch, verifyVerbatim } from "./source-grounding.js";

export type MemoryKind = "context" | "decision" | "evidence";
export type MemoryScope = "private" | "capitalised";

/** The structural event anchor — what makes `event_shaped` a code check, not prose. */
export interface MemoryEventAnchor {
  /** The instant it happened (epoch-ms or turn count). REQUIRED — a generalization has none. */
  at: number;
  /** A closed event-kind aligned to `memory_kind`. */
  kind: string;
  /** A structured locator, shared with `provenance.source`. */
  ref: string;
}

/** Structured citation: a cited string + the named source it must appear in (§4). */
export interface MemoryProvenance {
  cited: string;
  source: string;
}

/** The note handed over by the producer (h2a). h2a authors ALL of it. */
export interface MemoryNoteInput {
  node_type: "MemoryNote";
  memory_kind: MemoryKind;
  /** `"agent-work"` or `"human:<id>"` only — never a persona/identity/voice (§3.3.1). */
  subject: string;
  t: number;
  t_end?: number;
  t_src: string;
  event: MemoryEventAnchor;
  provenance: MemoryProvenance;
  principal_owner: string;
  scope: MemoryScope;
  /** Required when `subject` is a human (§3.5). */
  purpose?: string;
  /** Retention/TTL bound; required when `subject` is a human (§3.5). */
  retention?: number | string;
  [key: string]: unknown;
}

export interface AdmissionDeps {
  /** Resolve a source locator to its raw text for `verifyVerbatim`; `null` when unresolvable. */
  resolveSource: (ref: string) => string | null;
  /** The storage write-path (injected — anti-cycle + testable). Appends the admitted node. */
  appendNode: (node: Record<string, unknown>) => Promise<{ created: boolean }>;
}

export type AdmissionOutcome =
  | { admitted: true; id: string }
  | { admitted: false; reason: string };

const MEMORY_KINDS = new Set<string>(["context", "decision", "evidence"]);
const MEMORY_SCOPES = new Set<string>(["private", "capitalised"]);

function isHumanSubject(s: unknown): s is string {
  return typeof s === "string" && s.startsWith("human:") && s.length > "human:".length;
}
function isValidSubject(s: unknown): boolean {
  return s === "agent-work" || isHumanSubject(s);
}

/** Stable content-addressed id for a note (deterministic, no clock/random). */
function memoryNoteId(note: MemoryNoteInput): string {
  const canonical = JSON.stringify([
    note.principal_owner,
    note.subject,
    note.event?.ref,
    note.event?.at,
    note.provenance?.cited,
    note.t,
  ]);
  return `mem:${createHash("sha256").update(canonical).digest("hex").slice(0, 16)}`;
}

function refuse(reason: string): AdmissionOutcome {
  return { admitted: false, reason };
}

/**
 * The admission gate. Runs the contract's checks IN ORDER; ALL must pass. On a
 * refusal, NOTHING is stored (no silent no-op). On success, stamps the fixed
 * admission fields and appends the note as `review_status: "pending"` (promotion
 * to `accepted` is the D11 gate — OUT of this perimeter).
 *
 * Single-note by construction: it admits ONE note and never assembles a
 * subject-human profile — the UserModel projection prohibition (§3.2/§3.3.3) is a
 * recall-surface invariant enforced separately (charter: temporal-recall).
 */
export async function admitMemoryNote(
  note: MemoryNoteInput,
  deps: AdmissionDeps,
): Promise<AdmissionOutcome> {
  // 1. schema + closed enum (§3.1)
  if (!note || note.node_type !== "MemoryNote") return refuse("node_type must be 'MemoryNote'");
  if (!MEMORY_KINDS.has(note.memory_kind)) {
    return refuse(`memory_kind not in the closed enum {context,decision,evidence}: ${String(note.memory_kind)}`);
  }

  // 2. persona: subject predicate (§3.3.1)
  if (!isValidSubject(note.subject)) {
    return refuse(`subject must be 'agent-work' or 'human:<id>', not ${String(note.subject)}`);
  }

  // 3. persona: event_shaped is STRUCTURAL (§3.3.2) — a machine-verifiable anchor,
  //    NOT a writer flag and NOT a prose classifier. A generalization has no `at`.
  const ev = note.event as MemoryEventAnchor | undefined;
  if (!ev || typeof ev !== "object") {
    return refuse("event anchor is required (event_shaped is structural, not prose)");
  }
  if (typeof ev.at !== "number" || !Number.isFinite(ev.at)) {
    return refuse("event.at (the instant it happened) is required and must be numeric — a generalization has no instant");
  }
  if (typeof ev.kind !== "string" || !ev.kind) return refuse("event.kind is required");
  if (typeof ev.ref !== "string" || !ev.ref) return refuse("event.ref (locator) is required");

  // 4. tenancy neutral hook (§3.6) — the FIELDS only, never the parked exec logic
  if (typeof note.principal_owner !== "string" || !note.principal_owner) {
    return refuse("principal_owner is required (§3.6)");
  }
  if (!MEMORY_SCOPES.has(note.scope)) {
    return refuse(`scope must be 'private' or 'capitalised', not ${String(note.scope)}`);
  }

  // 5. retention controls for a subject-human fact (§3.5)
  if (isHumanSubject(note.subject)) {
    if (typeof note.purpose !== "string" || !note.purpose) {
      return refuse("a subject-human fact requires a `purpose` (§3.5)");
    }
    if (note.retention === undefined || note.retention === null) {
      return refuse("a subject-human fact requires a `retention` bound (§3.5)");
    }
  }

  // 6. citation gate — verifyVerbatim ONLY (§4): the cited string must be literally
  //    present in the named source. This checks the citation, NOT the form (§3.3)
  //    and NOT the truth of the lesson.
  const prov = note.provenance;
  if (!prov || typeof prov.cited !== "string" || typeof prov.source !== "string") {
    return refuse("provenance {cited, source} is required (§4)");
  }
  const raw = deps.resolveSource(prov.source);
  if (raw == null) return refuse(`provenance source could not be resolved: ${prov.source}`);
  if (!verifyVerbatim(prov.cited, normalizeForMatch(raw))) {
    return refuse("citation failed verifyVerbatim: the cited string is not present in the named source");
  }

  // All checks passed — stamp the fixed admission fields (graphify authors nothing else).
  const id = memoryNoteId(note);
  const admitted: Record<string, unknown> = {
    ...note,
    id,
    trust: "asserted", // fixed tier (§1/§3.1)
    review_status: "pending", // enters behind the binary gate; promotion is OUT of this perimeter (D11)
    reconcilable: false, // opt-out by construction (§3.4)
  };
  await deps.appendNode(admitted);
  return { admitted: true, id };
}

// ---------------------------------------------------------------------------
// Tombstone authority hook (§3.5) — the CHECK is graphify's; the append is
// storage's write-path (injected, OUT of this perimeter).
// ---------------------------------------------------------------------------

export type TombstoneTarget =
  | { kind: "node"; id: string }
  | { kind: "edge"; source: string; target: string; relation?: string };

export interface TombstoneRequest {
  target: TombstoneTarget;
  /** The principal that owns the target being erased. */
  principal_owner: string;
}

export interface TombstoneAuthority {
  /** Who requests the erasure. */
  requester: string;
  /**
   * For a subject-human fact, a SIGNED authorization (Ed25519 of the
   * `principal_owner` or a signed mandate) is required (§9.4); its cryptographic
   * verification is the caller's (h2a) — this gate checks ownership.
   */
  signedAuthorization?: unknown;
}

export interface TombstoneDeps {
  appendTombstone: (tombstone: { target: TombstoneTarget; principal_owner: string }) => Promise<{ applied: boolean }>;
}

/**
 * Authority check for an erasure (§3.5): only the `principal_owner` (or an agent
 * it MANDATES) may erase. graphify KEEPS this check; the actual tombstone append
 * is storage's write-path (injected). Authority never rests on a fabricable
 * asserted `by`.
 */
export async function requestTombstone(
  req: TombstoneRequest,
  auth: TombstoneAuthority,
  deps: TombstoneDeps,
): Promise<{ applied: boolean; reason?: string }> {
  const ownerAuthorised = auth.requester === req.principal_owner; // mandated-agent path: future
  if (!ownerAuthorised) {
    return { applied: false, reason: "erasure requires the principal_owner (or a mandated agent)" };
  }
  return deps.appendTombstone({ target: req.target, principal_owner: req.principal_owner });
}

/**
 * graphify-memory v1 — the RECALL surface (SPEC_AGENT_MEMORY_SUBSTRATE, ratified
 * @87a8cd05..cd7fad55). The read side that makes the admitted substrate usable:
 * it recalls `MemoryNote` nodes through the SAME T5/T6 temporal predicate and
 * enforces the recall-surface invariants that are graphify-side (charter:
 * temporal-recall). It is the mirror of the admission gate — admission is the
 * write predicate, this is the read predicate — and it authors NO memory.
 *
 * What this surface guarantees, and deliberately does NOT:
 *  - It REUSES `overlapsTemporalWindow` (the exported T5/T6 membership predicate)
 *    rather than keeping a second, drifting copy.
 *  - It enforces tenancy access (§3.6): a `private` note is visible ONLY to its
 *    `principal_owner`; `capitalised` notes are shared; a note whose tenancy
 *    cannot be verified fails CLOSED (never recalled).
 *  - It folds tombstoned targets out at PROJECTION (§3.5) — A2 with teeth — and a
 *    tombstoned node cannot resurface through an edge (this surface is notes-only,
 *    so an edge can never reintroduce an erased subject).
 *  - It RETAINS the trust tier + review_status + provenance on every note (§1):
 *    a `pending` note is disclosed as pending, never presented as ground truth.
 *  - PROJECTION PROHIBITION (§3.3.3): it offers NO identity-profile projection.
 *    `human:<id>` notes are returned INDIVIDUALLY, never assembled into a ranked
 *    `UserModel`. The prohibition is structural — there is no such entry point.
 *
 * Deterministic, provider-neutral, no LLM, no network, no h2a import (anti-cycle).
 */
import { overlapsTemporalWindow } from "./temporal-recall.js";

export const MEMORY_RECALL_SCHEMA = "graphify.memory-recall/v1" as const;

/** The principal performing the recall; tenancy access is evaluated against it (§3.6). */
export interface MemoryRecallContext {
  principal_owner: string;
}

/** Exactly one of `asOf` (T6 point) or `window` (T5 span) must be supplied. */
export interface MemoryRecallOptions {
  /** T6 point recall: the note must be live at this instant, `[asOf, asOf]`. */
  asOf?: number;
  /** T5 window recall: inclusive `[since, until]`; `null` leaves that side open. */
  window?: { sinceMs: number | null; untilMs: number | null };
}

/** A compensating erasure event (§3.5). It folds its target out of EVERY projection. */
export interface MemoryTombstone {
  target:
    | { kind: "node"; id: string }
    | { kind: "edge"; source: string; target: string; relation?: string };
  /** The principal that owns the erased target (authority is checked at request time). */
  principal_owner: string;
}

export interface MemoryRecallInput {
  nodes?: Record<string, unknown>[];
  links?: Record<string, unknown>[];
  edges?: Record<string, unknown>[];
}

/** A recalled note, carried verbatim — the tier and provenance are RETAINED (§1). */
export type RecalledMemoryNote = Record<string, unknown> & {
  id: string;
  node_type: "MemoryNote";
  subject: string;
  t: number;
  trust: unknown;
  review_status: unknown;
  scope: string;
  principal_owner: string;
};

export interface MemoryRecallResult {
  schema: typeof MEMORY_RECALL_SCHEMA;
  /** Individual notes — NEVER an assembled identity profile (§3.3.3). */
  notes: RecalledMemoryNote[];
  /** Structural disclosure that no profile/UserModel projection was performed. */
  projection: "notes-only";
  requestingPrincipal: string;
  asOfMs: number | null;
  window: { sinceMs: number | null; untilMs: number | null } | null;
  /** T6 contract: the full matching set, never silently truncated. */
  unpaged: true;
}

function compareText(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

/** Resolve the recall bounds from exactly one of the two mutually exclusive modes. */
function resolveBounds(options: MemoryRecallOptions): {
  fromMs: number;
  toMs: number;
  asOfMs: number | null;
  window: { sinceMs: number | null; untilMs: number | null } | null;
} {
  const hasAsOf = typeof options.asOf === "number";
  const hasWindow = options.window !== undefined && options.window !== null;
  if (hasAsOf === hasWindow) {
    throw new Error("recallMemory requires exactly one of { asOf } or { window }");
  }
  if (hasAsOf) {
    const at = options.asOf as number;
    if (!Number.isFinite(at)) throw new RangeError("asOf must be a finite epoch-ms instant");
    return { fromMs: at, toMs: at, asOfMs: at, window: null };
  }
  const w = options.window as { sinceMs: number | null; untilMs: number | null };
  const fromMs = w.sinceMs ?? Number.NEGATIVE_INFINITY;
  const toMs = w.untilMs ?? Number.POSITIVE_INFINITY;
  if (fromMs > toMs) throw new RangeError("recallMemory window requires sinceMs <= untilMs");
  return { fromMs, toMs, asOfMs: null, window: { sinceMs: w.sinceMs, untilMs: w.untilMs } };
}

/**
 * Tenancy visibility (§3.6): a `capitalised` note is shared across principals; a
 * `private` note is visible ONLY within its `principal_owner`. A note whose
 * tenancy cannot be verified (missing owner, unknown scope) fails CLOSED — the
 * recall would rather omit a note than leak one across tenants.
 */
function isVisibleTo(node: Record<string, unknown>, requester: string): boolean {
  const owner = node.principal_owner;
  const scope = node.scope;
  if (typeof owner !== "string" || owner.length === 0) return false;
  if (scope === "capitalised") return true;
  if (scope === "private") return owner === requester;
  return false;
}

/**
 * Recall the memory notes live at the requested instant/window and visible to the
 * requesting principal, folding out tombstoned targets. Pure: the input document
 * is never mutated and notes are carried verbatim.
 */
export function recallMemory(
  input: MemoryRecallInput,
  ctx: MemoryRecallContext,
  options: MemoryRecallOptions,
  tombstones: readonly MemoryTombstone[] = [],
): MemoryRecallResult {
  if (typeof ctx?.principal_owner !== "string" || ctx.principal_owner.length === 0) {
    throw new Error("recallMemory requires a ctx.principal_owner");
  }
  const { fromMs, toMs, asOfMs, window } = resolveBounds(options);

  // Tombstoned node ids fold OUT at projection (§3.5). Because this surface is
  // notes-only, a tombstoned node can never resurface through an edge — the edge
  // cascade is satisfied by construction, not by a second pass.
  const tombstonedNodeIds = new Set<string>();
  for (const t of tombstones) {
    if (t.target.kind === "node") tombstonedNodeIds.add(t.target.id);
  }

  const rawNodes = Array.isArray(input.nodes) ? input.nodes : [];
  const notes: RecalledMemoryNote[] = [];
  for (const node of rawNodes) {
    if (node.node_type !== "MemoryNote") continue;
    if (typeof node.id !== "string") continue;
    if (tombstonedNodeIds.has(node.id)) continue;
    if (!isVisibleTo(node, ctx.principal_owner)) continue;
    if (!overlapsTemporalWindow(node, fromMs, toMs)) continue;
    // Carried verbatim: trust, review_status and provenance are RETAINED (§1),
    // so a pending note is disclosed as pending and never dressed as ground truth.
    notes.push(node as RecalledMemoryNote);
  }

  // Deterministic order by (t, id). Human-subject and agent-subject notes are
  // treated IDENTICALLY — no per-subject ranking, no profile assembly (§3.3.3).
  notes.sort((a, b) => {
    const ta = typeof a.t === "number" ? a.t : 0;
    const tb = typeof b.t === "number" ? b.t : 0;
    return ta - tb || compareText(a.id, b.id);
  });

  return {
    schema: MEMORY_RECALL_SCHEMA,
    notes,
    projection: "notes-only",
    requestingPrincipal: ctx.principal_owner,
    asOfMs,
    window,
    unpaged: true,
  };
}

/**
 * Shared, source-centric grounding substrate.
 *
 * Citation grounding and typed entity linking intentionally share parsing,
 * normalized-to-raw relocation, and the verbatim gate. `rawSource` remains
 * authoritative: a SourceUnit's display text may be a trim/join projection of
 * OCR lines and must never be treated as a raw-file slice.
 */
import { readFileSync } from "node:fs";
import { isAbsolute, resolve as resolvePath } from "node:path";

/** NFKD deaccent + ascii-fold (drops combining marks, ligatures degrade). */
export function deaccent(s: string): string {
  return (s ?? "").normalize("NFKD").replace(/[̀-ͯ]/g, "");
}

const DOTTED_INITIAL_RUN_RE = /\b[a-z]\s*\.(?:\s*[a-z]\s*\.)+/g;

function normalizeForMatchBase(s: string): string {
  return deaccent(s ?? "")
    .replace(/œ/g, "oe")
    .replace(/æ/g, "ae")
    .replace(/Œ/g, "OE")
    .replace(/Æ/g, "AE")
    .toLowerCase()
    .replace(/\s+/g, " ")
    .trim();
}

function foldDottedInitialSpacing(s: string): string {
  return s.replace(DOTTED_INITIAL_RUN_RE, (run) => run.replace(/\s+/g, ""));
}

/** Canonical match form used by both matching and the verbatim gate. */
export function normalizeForMatch(s: string): string {
  return foldDottedInitialSpacing(normalizeForMatchBase(s));
}

export type SourceModality = "ocr-markdown" | "plain-text";

export interface SourceUnit {
  /** Paragraph display text; OCR paragraphs can be a trim/join projection. */
  text: string;
  page: number;
  section: string;
  paragraphIndex: number;
  /** Raw-file half-open boundaries covering this unit's source lines. */
  documentStart?: number;
  documentEnd?: number;
  /** Normalized unit text and its per-character raw document offsets. */
  normalizedText?: string;
  normToRaw?: number[];
}

export interface ImageContext {
  basename: string;
  page: number;
  section: string;
  prev: string;
  next: string;
}

export interface ParsedSource {
  modality: SourceModality;
  units: SourceUnit[];
  sectionToIndices: Map<string, number[]>;
  images: Map<string, ImageContext>;
  pageCount: number;
  /** Original file contents; the sole authority for occurrence slices. */
  rawSource?: string;
  /** Leading YAML-ish front matter, excluded from content units. */
  frontMatter?: Record<string, string>;
}

/** Detect modality from a source path. `.md` → OCR-markdown, else plain-text. */
export function detectModality(sourceFile: string): SourceModality {
  return /\.(md|markdown)$/i.test(sourceFile) ? "ocr-markdown" : "plain-text";
}

const FRONT_MATTER_KEY = /^[a-z_]+:\s/i;

interface BufferedLine {
  text: string;
  start: number;
  end: number;
}

function lineStarts(raw: string, lines: string[]): number[] {
  const starts: number[] = [];
  let offset = 0;
  for (const line of lines) {
    starts.push(offset);
    offset += line.length + 1;
  }
  return starts;
}

function trimmedLine(rawLine: string, start: number): BufferedLine | null {
  const text = rawLine.trim();
  if (!text) return null;
  const leading = rawLine.length - rawLine.trimStart().length;
  const trailing = rawLine.trimEnd().length;
  return { text, start: start + leading, end: start + trailing };
}

function frontMatterValue(line: string): [string, string] | null {
  const match = /^([a-zA-Z0-9_-]+):\s*(.*)$/u.exec(line.trim());
  if (!match) return null;
  const key = match[1]!;
  const value = match[2]!.trim().replace(/^(?:"([\s\S]*)"|'([\s\S]*)')$/u, "$1$2");
  return [key, value];
}

function makeUnit(
  raw: string,
  lines: BufferedLine[],
  page: number,
  section: string,
  paragraphIndex: number,
): SourceUnit {
  const documentStart = lines[0]!.start;
  const documentEnd = lines[lines.length - 1]!.end;
  const table = buildNormToRawMap(raw.slice(documentStart, documentEnd));
  return {
    text: lines.map((line) => line.text).join(" ").trim(),
    page,
    section,
    paragraphIndex,
    documentStart,
    documentEnd,
    normalizedText: table.norm,
    normToRaw: table.map.map((offset) => documentStart + offset),
  };
}

function addUnit(
  raw: string,
  units: SourceUnit[],
  sectionToIndices: Map<string, number[]>,
  lines: BufferedLine[],
  page: number,
  section: string,
): SourceUnit | null {
  if (lines.length === 0) return null;
  const unit = makeUnit(raw, lines, page, section, units.length);
  if (!unit.text || unit.text.startsWith("![")) return null;
  units.push(unit);
  const arr = sectionToIndices.get(section) ?? [];
  arr.push(unit.paragraphIndex);
  sectionToIndices.set(section, arr);
  return unit;
}

function parseOcrMarkdown(raw: string): ParsedSource {
  const lines = raw.split("\n");
  const starts = lineStarts(raw, lines);
  const units: SourceUnit[] = [];
  const sectionToIndices = new Map<string, number[]>();
  const images = new Map<string, ImageContext>();
  const frontMatter: Record<string, string> = {};
  let page = 1;
  let section = "";
  let buf: BufferedLine[] = [];
  let pendingImages: string[] = [];
  let inFrontMatter = false;
  let frontMatterDone = false;
  let i = 0;
  if (lines[0]?.trim() === "---") {
    inFrontMatter = true;
    i = 1;
  }

  const flush = (): void => {
    const unit = addUnit(raw, units, sectionToIndices, buf, page, section);
    buf = [];
    if (!unit) return;
    for (const filename of pendingImages) {
      const ctx = images.get(filename);
      if (ctx && !ctx.next) ctx.next = unit.text;
    }
    pendingImages = [];
  };

  for (; i < lines.length; i += 1) {
    const rawLine = lines[i] ?? "";
    const s = rawLine.trim();
    if (inFrontMatter && !frontMatterDone) {
      if (s === "---") {
        frontMatterDone = true;
        inFrontMatter = false;
      } else if (s !== "" && !FRONT_MATTER_KEY.test(s)) {
        inFrontMatter = false;
        frontMatterDone = true;
        i -= 1;
      } else {
        const entry = frontMatterValue(rawLine);
        if (entry) frontMatter[entry[0]] = entry[1];
      }
      continue;
    }
    if (s === "---") {
      flush();
      page += 1;
      continue;
    }
    if (/^#{1,4}\s/.test(s)) {
      flush();
      section = s.replace(/^#{1,4}\s+/, "").trim();
      continue;
    }
    const img = /^!\[[^\]]*\]\(([^)]+)\)/.exec(s);
    if (img) {
      flush();
      const filename = basenameOf(img[1] ?? "");
      const prev = units.length > 0 ? (units[units.length - 1]?.text ?? "") : "";
      images.set(filename, { basename: filename, page, section, prev, next: "" });
      pendingImages.push(filename);
      continue;
    }
    if (s === "") {
      flush();
      continue;
    }
    const line = trimmedLine(rawLine, starts[i]!);
    if (line) buf.push(line);
  }
  flush();
  return { modality: "ocr-markdown", units, sectionToIndices, images, pageCount: page, rawSource: raw, frontMatter };
}

function parsePlainText(raw: string): ParsedSource {
  const lines = raw.split("\n");
  const starts = lineStarts(raw, lines);
  const units: SourceUnit[] = [];
  const sectionToIndices = new Map<string, number[]>();
  let section = "";
  let buf: BufferedLine[] = [];
  const flush = (): void => {
    addUnit(raw, units, sectionToIndices, buf, 1, section);
    buf = [];
  };
  for (let i = 0; i < lines.length; i += 1) {
    const rawLine = lines[i] ?? "";
    const s = rawLine.trim();
    if (/^#{1,4}\s/.test(s)) {
      flush();
      section = s.replace(/^#{1,4}\s+/, "").trim();
      continue;
    }
    if (isHeadingLine(s, buf.length === 0)) {
      flush();
      section = s;
      continue;
    }
    if (s === "") {
      flush();
      continue;
    }
    const line = trimmedLine(rawLine, starts[i]!);
    if (line) buf.push(line);
  }
  flush();
  return {
    modality: "plain-text",
    units,
    sectionToIndices,
    images: new Map(),
    pageCount: 1,
    rawSource: raw,
    frontMatter: {},
  };
}

function isHeadingLine(s: string, atParagraphStart: boolean): boolean {
  if (!s || !atParagraphStart) return false;
  if (/^(chapter|part|book|adventure|story)\b/i.test(s) && s.length <= 80) return true;
  const words = s.split(/\s+/);
  if (words.length > 8 || s.length > 80) return false;
  const letters = s.replace(/[^a-zA-ZÀ-ÿ]/g, "");
  if (letters.length < 3) return false;
  const upper = s.replace(/[^A-ZÀ-Þ]/g, "");
  return upper.length / letters.length >= 0.7;
}

function basenameOf(path: string): string {
  const normalized = path.replace(/\\/g, "/");
  const index = normalized.lastIndexOf("/");
  return index >= 0 ? normalized.slice(index + 1) : normalized;
}

/** Parse any supported source modality. */
export function parseSource(raw: string, modality: SourceModality): ParsedSource {
  return modality === "ocr-markdown" ? parseOcrMarkdown(raw) : parsePlainText(raw);
}

const QUOTE_BEFORE = 110;
const QUOTE_AFTER = 210;
const QUOTE_MAXLEN = 320;
const OPEN_BOUNDARY = new Set([" ", "\n", "«", "(", '"', "“"]);
const CLOSE_BOUNDARY = new Set([" ", "\n", ".", "!", "?", "»", ")", '"', "”"]);

/** Return a RAW context window around an offset. */
export function windowQuote(text: string, offset: number): string {
  let a = Math.max(0, offset - QUOTE_BEFORE);
  let b = Math.min(text.length, offset + QUOTE_AFTER);
  while (a > 0 && !OPEN_BOUNDARY.has(text[a] ?? "")) a -= 1;
  while (b < text.length && !CLOSE_BOUNDARY.has(text[b] ?? "")) b += 1;
  let quote = text.slice(a, b).trim();
  if (a > 0) quote = "… " + quote;
  if (b < text.length) quote += " …";
  quote = quote.replace(/\s+/g, " ");
  return quote.length > QUOTE_MAXLEN ? quote.slice(0, QUOTE_MAXLEN).trim() : quote;
}

/** Hard gate shared by all grounding producers. */
export function verifyVerbatim(quote: string, normalizedSource: string): boolean {
  if (!quote) return false;
  const core = quote.replace(/^…\s*/, "").replace(/\s*…$/, "");
  const needle = normalizeForMatch(core);
  return Boolean(needle) && normalizedSource.includes(needle);
}

/** Build a normalized offset → raw offset table for one raw string. */
export function buildNormToRawMap(rawText: string): { norm: string; map: number[] } {
  const normChars: string[] = [];
  const map: number[] = [];
  let pendingSpace = false;
  let sawNonSpace = false;
  for (let i = 0; i < rawText.length; i += 1) {
    const ch = rawText[i] ?? "";
    const piece = normalizeForMatchBase(ch);
    if (piece === "") {
      if (/\s/.test(ch)) pendingSpace = true;
      continue;
    }
    if (pendingSpace && sawNonSpace) {
      normChars.push(" ");
      map.push(i);
    }
    pendingSpace = false;
    for (const normalized of piece) {
      normChars.push(normalized);
      map.push(i);
    }
    sawNonSpace = true;
  }
  const norm = normChars.join("");
  const foldedChars: string[] = [];
  const foldedMap: number[] = [];
  let copiedUntil = 0;
  DOTTED_INITIAL_RUN_RE.lastIndex = 0;
  let match: RegExpExecArray | null;
  while ((match = DOTTED_INITIAL_RUN_RE.exec(norm)) !== null) {
    const start = match.index;
    const end = start + match[0].length;
    for (let i = copiedUntil; i < start; i += 1) {
      foldedChars.push(norm[i] ?? "");
      foldedMap.push(map[i] ?? 0);
    }
    for (let i = start; i < end; i += 1) {
      const char = norm[i] ?? "";
      if (char === " ") continue;
      foldedChars.push(char);
      foldedMap.push(map[i] ?? 0);
    }
    copiedUntil = end;
  }
  for (let i = copiedUntil; i < norm.length; i += 1) {
    foldedChars.push(norm[i] ?? "");
    foldedMap.push(map[i] ?? 0);
  }
  return { norm: foldedChars.join(""), map: foldedMap };
}

/** Locate a normalized term's raw offset, or -1 when it is absent. */
export function rawOffsetForTerm(rawText: string, normTerm: string): number {
  if (!normTerm) return -1;
  const { norm, map } = buildNormToRawMap(rawText);
  const at = norm.indexOf(normTerm);
  return at < 0 ? -1 : (map[at] ?? -1);
}

export interface ResolveSourceOptions {
  root: string;
  searchRoots?: string[];
}

/** Resolve a source relative to the configured root and optional search roots. */
export function resolveSourcePath(sourceFile: string, options: ResolveSourceOptions): string | null {
  if (!sourceFile) return null;
  const candidates: string[] = [];
  if (isAbsolute(sourceFile)) candidates.push(sourceFile);
  candidates.push(resolvePath(options.root, sourceFile));
  for (const root of options.searchRoots ?? []) candidates.push(resolvePath(root, sourceFile));
  for (const candidate of candidates) {
    try {
      readFileSync(candidate);
      return candidate;
    } catch {
      // Try the next location.
    }
  }
  return null;
}

/**
 * Read-only temporal graph recall (SPEC_AGENTSTATS_TIMEORIENTED, T6).
 *
 * This module projects the shared `t` / `t_end` graph contract at one instant.
 * It deliberately models neither authored memory nor semantic relevance:
 * configured stores delegate to the optional queryWindow port, while the
 * no-store path applies the same predicate directly to graph.json.
 */
import { existsSync, readFileSync } from "node:fs";
import { createHash } from "node:crypto";
import { join, resolve } from "node:path";

import type { SerializedGraphData } from "./graph.js";
import { resolveGraphInputPath } from "./paths.js";
import { loadProjectConfig } from "./project-config.js";
import { resolveStoreConfig } from "./storage/config.js";
import { resolveGraphStore } from "./storage/registry.js";
import type {
  GraphStore,
  GraphStoreConfig,
  GraphStoreSnapshotMeta,
  GraphTimeWindow,
  GraphTimeWindowEdge,
  GraphTimeWindowNode,
  StoreTestDeps,
} from "./storage/types.js";
import type { NormalizedProjectConfig } from "./types.js";

export const TEMPORAL_RECALL_SCHEMA = "graphify.temporal-recall/v1" as const;

interface TemporalSerializedGraph extends SerializedGraphData {
  topology_signature?: unknown;
}

export interface TemporalRecallOptions {
  /** Safe integer epoch-ms, or ISO-8601 carrying an explicit Z/UTC offset. */
  asOf: string | number;
  /** Explicit graph.json source. Selecting it forces the file path. */
  graph?: string;
  /** Graphify project config (state dir plus optional storage mirror). */
  config?: string;
  /** Explicit GraphStore id. Otherwise env/config may select a store. */
  store?: string;
}

export interface TemporalRecallSnapshot {
  topologySignatureSha256: string;
  pushedAt: string;
  toolVersion: string;
}

export type TemporalRecallSource =
  | {
      kind: "file";
      path: string;
      topologySignatureSha256?: string;
      provenance?: unknown;
      freshness: "unverified";
    }
  | {
      kind: "store";
      storeId: string;
      namespace?: string;
      snapshot: TemporalRecallSnapshot | null;
      freshness: "unverified";
    };

export interface TemporalRecallResult extends GraphTimeWindow {
  schema: typeof TEMPORAL_RECALL_SCHEMA;
  asOfMs: number;
  asOfIso: string;
  source: TemporalRecallSource;
  /** T6 returns the complete matching snapshot and never silently truncates. */
  unpaged: true;
}

export interface TemporalRecallDeps {
  /** Hermetic environment map for store selection/config tests. */
  env?: NodeJS.ProcessEnv;
  /** Optional GraphStore resolver injection for tests/embedders. */
  resolveStore?: (id: string, config: GraphStoreConfig) => Promise<GraphStore>;
  /** Optional backend driver injection forwarded to the production registry. */
  storeTestDeps?: StoreTestDeps;
  /** Optional graph loader injection. Production reads/parses the named JSON file. */
  readGraph?: (path: string) => TemporalSerializedGraph;
}

export interface TemporalRecallCliOptions extends TemporalRecallOptions {
  /** Emit the machine result only. */
  json?: boolean;
}

export interface TemporalRecallCliDeps extends TemporalRecallDeps {
  /** Output sink; defaults to stdout through console.log. */
  log?: (line: string) => void;
}

const INTEGER_EPOCH = /^-?(?:0|[1-9]\d*)$/;
const EXPLICIT_ZONE_ISO = /^\d{4}-\d{2}-\d{2}T.+(?:Z|[+-]\d{2}:\d{2})$/i;

function assertEpochRange(value: number): number {
  if (!Number.isSafeInteger(value)) {
    throw new RangeError("--as-of epoch-ms must be a safe integer");
  }
  if (Number.isNaN(new Date(value).getTime())) {
    throw new RangeError("--as-of epoch-ms is outside the ISO date range");
  }
  return value;
}

/** Parse the deterministic T6 timestamp input contract. */
export function parseRecallTimestamp(value: string | number): number {
  if (typeof value === "number") return assertEpochRange(value);

  const raw = value.trim();
  if (INTEGER_EPOCH.test(raw)) return assertEpochRange(Number(raw));
  if (!EXPLICIT_ZONE_ISO.test(raw)) {
    throw new Error(
      "--as-of must be safe integer epoch-ms or ISO-8601 with an explicit Z/UTC offset",
    );
  }
  const parsed = Date.parse(raw);
  if (!Number.isFinite(parsed)) {
    throw new Error("--as-of contains an invalid ISO-8601 timestamp");
  }
  return assertEpochRange(parsed);
}

function hasOwn(record: Record<string, unknown>, key: string): boolean {
  return Object.prototype.hasOwnProperty.call(record, key);
}

function temporalBounds(
  record: Record<string, unknown>,
  fromMs: number,
  toMs: number,
): { t: number; tEnd?: number } | undefined {
  const t = record.t;
  if (typeof t !== "number" || !Number.isFinite(t) || t > toMs) return undefined;
  if (!hasOwn(record, "t_end")) return { t };

  const tEnd = record.t_end;
  if (
    typeof tEnd !== "number" ||
    !Number.isFinite(tEnd) ||
    tEnd < t ||
    tEnd < fromMs
  ) {
    return undefined;
  }
  return { t, tEnd };
}

/**
 * The shared T5/T6 record-level membership predicate: `t <= toMs AND (t_end
 * absent OR t_end >= fromMs)`, with untimed, malformed and inverted spans
 * excluded.
 *
 * Exported so the file-backend build-time window (SPEC §3(a)) slices with the
 * exact same semantics instead of keeping a second, drifting copy. Infinite
 * bounds are accepted here (a half-open slice); the T5 store port still
 * requires finite ordered bounds.
 */
export function overlapsTemporalWindow(
  record: Record<string, unknown>,
  fromMs: number,
  toMs: number,
): boolean {
  return temporalBounds(record, fromMs, toMs) !== undefined;
}

function canonicalTemporalNode(
  raw: Record<string, unknown>,
  fromMs: number,
  toMs: number,
): GraphTimeWindowNode | undefined {
  if (typeof raw.id !== "string") return undefined;
  const bounds = temporalBounds(raw, fromMs, toMs);
  if (!bounds) return undefined;

  const { id: _rawId, ...attributes } = raw;
  const node: GraphTimeWindowNode = {
    ...attributes,
    id: raw.id,
    label: typeof raw.label === "string" && raw.label.length > 0 ? raw.label : raw.id,
    t: bounds.t,
  };

  // These are canonical GraphStore fields, so malformed file values cannot
  // spoof a different provider-neutral shape.
  delete node.node_type;
  delete node.community;
  delete node.t_end;
  if (typeof raw.node_type === "string" && raw.node_type.length > 0) {
    node.node_type = raw.node_type;
  }
  if (typeof raw.community === "number" && Number.isFinite(raw.community)) {
    node.community = raw.community;
  }
  if (bounds.tEnd !== undefined) node.t_end = bounds.tEnd;
  return node;
}

function canonicalTemporalEdge(
  raw: Record<string, unknown>,
  fromMs: number,
  toMs: number,
): GraphTimeWindowEdge | undefined {
  if (typeof raw.source !== "string" || typeof raw.target !== "string") return undefined;
  const bounds = temporalBounds(raw, fromMs, toMs);
  if (!bounds) return undefined;

  const { source: _rawSource, target: _rawTarget, ...attributes } = raw;
  const edge: GraphTimeWindowEdge = {
    ...attributes,
    source: raw.source,
    target: raw.target,
    relation: typeof raw.relation === "string" ? raw.relation : "RELATES_TO",
    t: bounds.t,
  };

  delete edge.confidence;
  delete edge.t_end;
  if (typeof raw.confidence === "string" && raw.confidence.length > 0) {
    edge.confidence = raw.confidence;
  }
  if (bounds.tEnd !== undefined) edge.t_end = bounds.tEnd;
  return edge;
}

function compareText(a: string, b: string): number {
  return a < b ? -1 : a > b ? 1 : 0;
}

function topologySignatureSha256(signature: string): string {
  return `sha256:${createHash("sha256").update(signature, "utf-8").digest("hex")}`;
}

function discloseSnapshot(meta: GraphStoreSnapshotMeta): TemporalRecallSnapshot {
  return {
    topologySignatureSha256: topologySignatureSha256(meta.topologySignature),
    pushedAt: meta.pushedAt,
    toolVersion: meta.toolVersion,
  };
}

function sortWindow(window: GraphTimeWindow): GraphTimeWindow {
  const nodes = [...window.nodes].sort(
    (a, b) => a.t - b.t || compareText(a.id, b.id),
  );
  const edges = [...window.edges].sort(
    (a, b) =>
      a.t - b.t ||
      compareText(a.source, b.source) ||
      compareText(a.target, b.target) ||
      compareText(a.relation, b.relation),
  );
  return { nodes, edges };
}

/**
 * Pure graph.json fallback. Node and edge membership is deliberately
 * independent, so this is not an induced-subgraph operation.
 */
export function filterTemporalWindow(
  raw: TemporalSerializedGraph,
  fromMs: number,
  toMs: number,
): GraphTimeWindow {
  if (!Number.isFinite(fromMs) || !Number.isFinite(toMs)) {
    throw new RangeError("temporal window bounds must be finite numbers");
  }
  if (fromMs > toMs) {
    throw new RangeError("temporal window requires fromMs <= toMs");
  }

  const rawNodes = Array.isArray(raw.nodes) ? raw.nodes : [];
  const rawEdges = Array.isArray(raw.links)
    ? raw.links
    : Array.isArray(raw.edges)
      ? raw.edges
      : [];
  const nodes = rawNodes
    .map((node) => canonicalTemporalNode(node, fromMs, toMs))
    .filter((node): node is GraphTimeWindowNode => node !== undefined);
  const edges = rawEdges
    .map((edge) => canonicalTemporalEdge(edge, fromMs, toMs))
    .filter((edge): edge is GraphTimeWindowEdge => edge !== undefined);
  return sortWindow({ nodes, edges });
}

function loadConfig(configPath: string | undefined): NormalizedProjectConfig | undefined {
  return configPath ? loadProjectConfig(resolve(configPath)) : undefined;
}

function selectedStoreId(
  options: TemporalRecallOptions,
  projectConfig: NormalizedProjectConfig | undefined,
  env: NodeJS.ProcessEnv,
): string | undefined {
  return options.store ?? env.GRAPHIFY_STORE ?? projectConfig?.storage?.mirrors?.[0]?.backend;
}

function readTemporalGraph(path: string, deps: TemporalRecallDeps): TemporalSerializedGraph {
  if (deps.readGraph) return deps.readGraph(path);
  const parsed: unknown = JSON.parse(readFileSync(path, "utf-8"));
  if (parsed === null || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error(`graph file must contain a JSON object: ${path}`);
  }
  return parsed as TemporalSerializedGraph;
}

async function openStore(
  id: string,
  config: GraphStoreConfig,
  deps: TemporalRecallDeps,
): Promise<GraphStore> {
  if (deps.resolveStore) return deps.resolveStore(id, config);
  return resolveGraphStore(id, config, deps.storeTestDeps);
}

/** Execute one read-only point-in-time graph projection. */
export async function recallAsOf(
  options: TemporalRecallOptions,
  deps: TemporalRecallDeps = {},
): Promise<TemporalRecallResult> {
  if (options.graph && options.store) {
    throw new Error("--graph and --store are mutually exclusive recall sources");
  }
  const asOfMs = parseRecallTimestamp(options.asOf);
  const asOfIso = new Date(asOfMs).toISOString();
  const env = deps.env ?? process.env;
  const projectConfig = loadConfig(options.config);

  // An explicit graph path is an explicit source choice, even if the ambient
  // environment also names a store. Otherwise, once a store is selected, no
  // store error/capability miss/empty result may silently switch sources.
  const storeId = options.graph
    ? undefined
    : selectedStoreId(options, projectConfig, env);
  if (storeId) {
    const storeConfig = resolveStoreConfig(storeId, { projectConfig, env });
    const store = await openStore(storeId, storeConfig, deps);
    try {
      if (
        store.capabilities.queryWindow !== true ||
        typeof store.queryWindow !== "function"
      ) {
        throw new Error(
          `store '${storeId}' does not support temporal recall ` +
            "(requires capabilities.queryWindow and queryWindow())",
        );
      }
      const window = sortWindow(await store.queryWindow(asOfMs, asOfMs));
      const snapshot = await store.readSnapshotMeta().catch(() => undefined);
      return {
        schema: TEMPORAL_RECALL_SCHEMA,
        asOfMs,
        asOfIso,
        source: {
          kind: "store",
          storeId,
          ...(storeConfig.namespace ? { namespace: storeConfig.namespace } : {}),
          snapshot: snapshot ? discloseSnapshot(snapshot) : null,
          freshness: "unverified",
        },
        unpaged: true,
        ...window,
      };
    } finally {
      await store.close();
    }
  }

  const graphPath = options.graph
    ? resolve(options.graph)
    : projectConfig
      ? join(projectConfig.outputs.state_dir, "graph.json")
      : resolveGraphInputPath();
  if (!existsSync(graphPath) && !deps.readGraph) {
    throw new Error(`graph file not found: ${graphPath}`);
  }
  const raw = readTemporalGraph(graphPath, deps);
  const window = filterTemporalWindow(raw, asOfMs, asOfMs);
  const provenance = raw.graph?.provenance;
  return {
    schema: TEMPORAL_RECALL_SCHEMA,
    asOfMs,
    asOfIso,
    source: {
      kind: "file",
      path: graphPath,
      ...(typeof raw.topology_signature === "string"
        ? { topologySignatureSha256: topologySignatureSha256(raw.topology_signature) }
        : {}),
      ...(provenance !== undefined ? { provenance } : {}),
      freshness: "unverified",
    },
    unpaged: true,
    ...window,
  };
}

/** Compact non-claiming human rendering for the CLI. */
export function formatTemporalRecall(result: TemporalRecallResult): string {
  const snapshot = result.source.kind === "file"
    ? result.source.topologySignatureSha256 ?? "unknown"
    : result.source.snapshot?.topologySignatureSha256 ?? "unknown";
  const lines = [
    `Temporal graph recall at ${result.asOfIso} (${result.asOfMs})`,
    result.source.kind === "file"
      ? `Source: graph file ${result.source.path}`
      : `Source: store '${result.source.storeId}'` +
        (result.source.namespace ? ` (configured namespace: ${result.source.namespace})` : ""),
    `Snapshot identity: ${snapshot}`,
    "Freshness/provenance: unverified; result is unpaged and edges may lack returned endpoints.",
    `Nodes (${result.nodes.length}):`,
  ];
  for (const node of result.nodes) {
    const type = node.node_type ? ` [${node.node_type}]` : "";
    const end = node.t_end === undefined ? "open" : String(node.t_end);
    lines.push(`  ${JSON.stringify(node.id)}${type} ${JSON.stringify(node.label)} t=${node.t} t_end=${end}`);
  }
  lines.push(`Edges (${result.edges.length}):`);
  for (const edge of result.edges) {
    const end = edge.t_end === undefined ? "open" : String(edge.t_end);
    lines.push(
      `  ${JSON.stringify(edge.source)} --${JSON.stringify(edge.relation)}--> ` +
        `${JSON.stringify(edge.target)} t=${edge.t} t_end=${end}`,
    );
  }
  return lines.join("\n");
}

/** CLI runner kept separate from Commander registration for focused tests. */
export async function runTemporalRecall(
  options: TemporalRecallCliOptions,
  deps: TemporalRecallCliDeps = {},
): Promise<TemporalRecallResult> {
  const result = await recallAsOf(options, deps);
  const log = deps.log ?? ((line: string) => console.log(line));
  log(options.json ? JSON.stringify(result, null, 2) : formatTemporalRecall(result));
  return result;
}

/**
 * The agent-memory ADMISSION GATE (ratified contract SPEC_AGENT_MEMORY_SUBSTRATE
 * @87a8cd05..d8a4a448, wire-shape §9.4). Perimeter = the admission gate ONLY:
 * schema/enum (§3.1), the persona checks (§3.3: subject + STRUCTURAL event_shaped
 * + single-note/no-profile), reconcilable:false (§3.4), retention controls
 * (§3.5), principal_owner+scope neutral hook (§3.6), verifyVerbatim citation (§4).
 * OUT: the storage write-path (injected), the D11 promotion rule, the parked exec.
 *
 * Each predicate is encoded RED-first: a passing case AND a refusing case, so a
 * removed check makes its test fail (falsifiability).
 */
import { describe, expect, it, vi } from "vitest";

import {
  admitMemoryNote,
  requestTombstone,
  type AdmissionDeps,
  type MemoryNoteInput,
} from "../src/memory-admission.js";

const T = 1_750_000_000_000;

/** A source the citation resolves to; the cited string must appear in it. */
const SOURCE_TEXT = "on 2026-08-01 correction Y was applied because Z, cf artifact A";

function deps(overrides: Partial<AdmissionDeps> = {}): AdmissionDeps {
  return {
    resolveSource: vi.fn((ref: string) => (ref === "ref:A" ? SOURCE_TEXT : null)),
    appendNode: vi.fn(async () => ({ created: true })),
    ...overrides,
  };
}

/** A complete, admissible agent-work note. */
function validNote(over: Partial<MemoryNoteInput> = {}): MemoryNoteInput {
  return {
    node_type: "MemoryNote",
    memory_kind: "decision",
    subject: "agent-work",
    t: T,
    t_src: "authored-at",
    event: { at: T, kind: "decision-taken", ref: "ref:A" },
    provenance: { cited: "correction Y was applied", source: "ref:A" },
    principal_owner: "human:antoinefa",
    scope: "private",
    ...over,
  };
}

describe("admitMemoryNote — schema + closed enum (§3.1)", () => {
  it("admits a well-formed agent-work note and appends it once", async () => {
    const d = deps();
    const out = await admitMemoryNote(validNote(), d);
    expect(out.admitted).toBe(true);
    expect(d.appendNode).toHaveBeenCalledTimes(1);
  });

  it("refuses a memory_kind outside the closed enum, and stores NOTHING", async () => {
    const d = deps();
    const out = await admitMemoryNote(validNote({ memory_kind: "persona" as never }), d);
    expect(out.admitted).toBe(false);
    expect(d.appendNode).not.toHaveBeenCalled(); // no silent write on refusal
  });

  it("refuses a wrong node_type", async () => {
    const out = await admitMemoryNote(validNote({ node_type: "Agent" as never }), deps());
    expect(out.admitted).toBe(false);
  });
});

describe("admitMemoryNote — persona mechanism, held by code (§3.3)", () => {
  it("admits subject agent-work and subject human:<id>", async () => {
    expect((await admitMemoryNote(validNote({ subject: "agent-work" }), deps())).admitted).toBe(true);
    expect(
      (await admitMemoryNote(
        validNote({ subject: "human:antoinefa", purpose: "self-contained requests", retention: T + 1 }),
        deps(),
      )).admitted,
    ).toBe(true);
  });

  it("REFUSES a persona/identity subject (not in {agent-work, human:<id>})", async () => {
    for (const bad of ["persona", "voice:calm", "identity", "the agent"]) {
      expect((await admitMemoryNote(validNote({ subject: bad as never }), deps())).admitted).toBe(false);
    }
  });

  it("event_shaped is STRUCTURAL: refuses a generalization with no instant `at`", async () => {
    // A standing rule ("always X") has no single instant → structurally refused.
    const noAnchor = validNote();
    delete (noAnchor as { event?: unknown }).event;
    expect((await admitMemoryNote(noAnchor, deps())).admitted).toBe(false);

    const noAt = validNote({ event: { kind: "decision-taken", ref: "ref:A" } as never });
    expect((await admitMemoryNote(noAt, deps())).admitted).toBe(false);

    const nonNumericAt = validNote({ event: { at: "always" as never, kind: "k", ref: "ref:A" } });
    expect((await admitMemoryNote(nonNumericAt, deps())).admitted).toBe(false);
  });

  it("admission is single-note: it never assembles a profile (returns one id)", async () => {
    const out = await admitMemoryNote(validNote(), deps());
    expect(out.admitted).toBe(true);
    if (out.admitted) expect(typeof out.id).toBe("string");
  });
});

describe("admitMemoryNote — citation gate, verifyVerbatim only (§4)", () => {
